window.__finlexDocLoaded(10003,{"id":10003,"articles":[{"id":1000003,"no":"Decision Summary","heading":"Disaggregation of Level 3 Fair Value Inputs (IFRS 13.93(d) & 13.94)","text":"[Issue & Enforcement Decision]\n• The issuer presented Level 3 rental yield ranges separately by geography (6 classes) and by type of use (4 classes), with wide ranges of 200 to 550 basis points within classes.\n• The enforcer disagreed with the issuer's determination of classes of investment properties, requiring finer disaggregation so users can evaluate valuation sensitivity meaningfully.\n\n[Key Takeaway]\n• Under IFRS 13.93(d) and IFRS 13.94, quantitative information about significant unobservable inputs (such as capitalisation rates and rental yields) must be disaggregated by nature, characteristics, and risks—not masked by wide multi-hundred-bps ranges.\n\nSource (ESMA 29th Extract): https://www.esma.europa.eu/sites/default/files/2024-05/ESMA32-193237008-8267_29th_Extract_from_the_EECS_s_Database_of_Enforcement.pdf","seq":0}]});
